  if dev_id="$(printf '%s\n' "$identities" | grep -o '"Developer ID Application: [^"]*"' | head -1 | tr -d '"')" && [ -n "$dev_id" ]; then
    MEV_SIGN_IDENTITY="$dev_id"
  elif printf '%s\n' "$identities" | grep -q "\"$LOCAL_NAME\""; then
    MEV_SIGN_IDENTITY="$LOCAL_NAME"
  else
