    local opts=(--force --options runtime --sign "$MEV_SIGN_IDENTITY" --identifier "$identifier")
    # Apple's timestamp server only accepts Apple-issued certificates.
    case "$MEV_SIGN_IDENTITY" in "Developer ID"*) opts+=(--timestamp) ;; esac
    codesign "${opts[@]}" "$@"
  fi
}
